  const num = decimal === undefined ? BigInt(whole) : BigInt(whole) * 10n + BigInt(decimal);
  if (num <= 0n) {
    errors.push(issue('SOZOKU_UI_AREA_INVALID', fieldPath,
      '面積は0より大きい値で入力してください'));
  }
  return { unit: 'SQM', num: num.toString(10), den: decimal === undefined ? '1' : '10' };
