  if (value === undefined && defaultValue !== undefined) return defaultValue;
  if (!['yes', 'no', 'unknown'].includes(value)) {
    errors.push(issue('SOZOKU_UI_SELECTION_REQUIRED', fieldPath, `${label}を選択してください`));
    return 'unknown';
  }
  return value;
