    ...common(result, 'A'),
    criterion,
    criterionNotice: criterion.assumption,
    conclusion,
    optimizationDisclaimer: OPTIMIZATION_DISCLAIMER,
    nearUpperBound,
    rowSelectionDescription: ROW_SELECTION_DESCRIPTION,
    defaultCandidateRows: Object.freeze(defaults.map(candidateRow)),
